import random,itertools,json
random.seed(42)
N=7;t=3
E=[sum(1<<x for x in e) for k in [1,2] for e in itertools.combinations(range(N),k)]
def tau(es):
 return min(C.bit_count() for C in range(1<<N) if all(C&e for e in es))
for z in range(100000):
 fam=[random.sample(E,random.randrange(2,6)) for _ in range(t)]
 ok=True
 for S in range(1,1<<t):
  if tau([e for i in range(t) if S>>i&1 for e in fam[i]])<S.bit_count():ok=False;break
 if not ok:continue
 f=[0]*(1<<t)
 for S in range(1,1<<t):
  fs=[fam[i] for i in range(t) if S>>i&1]
  f[S]=max(sum(not(a&b) for a,b in itertools.combinations(c,2)) for c in itertools.product(*fs))
 for S in range(1<<t):
  for T in range(1<<t):
   if f[S]+f[T]>f[S&T]+f[S|T]:
    print('counter',fam,f,S,T,z);quit()
print('none')

